def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find a solid, nonzero separator between two equal-sized panels.
    for r in range(h):
        if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r]):
            if r > 0 and h - r - 1 == r:
                a, b = grid[:r], grid[r + 1:]
                return [[2 if a[i][j] and b[i][j] else 0
                         for j in range(w)] for i in range(r)]

    for c in range(w):
        color = grid[0][c]
        if color != 0 and all(grid[i][c] == color for i in range(h)):
            if c > 0 and w - c - 1 == c:
                return [[2 if grid[i][j] and grid[i][c + 1 + j] else 0
                         for j in range(c)] for i in range(h)]

    return [row[:] for row in grid]
